type FolderVisibilityAction = "default" | "collapse" | "expand";

function getFileBadge(extension: string): { label: string; color: string; background: string } {
    const ext = extension.toLowerCase();
    const colors =
        ["png", "jpg", "jpeg", "gif", "webp", "svg", "bmp", "tif", "tiff"].includes(ext)
            ? { color: "#c084fc", background: "rgba(192,132,252,0.12)" }
            : ext === "pdf"
              ? { color: "#f87171", background: "rgba(248,113,113,0.12)" }
              : ["mp3", "wav", "ogg", "flac", "aac", "m4a", "opus"].includes(ext)
                ? { color: "#4ade80", background: "rgba(74,222,128,0.12)" }
                : ["mp4", "mov", "webm", "mkv", "avi"].includes(ext)
                  ? { color: "#fb923c", background: "rgba(251,146,60,0.12)" }
                  : ["glb", "gltf", "obj", "fbx", "stl", "usd", "usdz", "blend", "uasset", "umap"].includes(ext)
                    ? { color: "#60a5fa", background: "rgba(96,165,250,0.12)" }
                    : ["zip", "rar", "7z", "tar", "gz"].includes(ext)
                      ? { color: "#fbbf24", background: "rgba(251,191,36,0.12)" }
                      : { color: "var(--mz-text-muted)", background: "var(--mz-bg-tertiary)" };
    return { label: ext.slice(0, 4).toUpperCase(), ...colors };
}

const [folderVisibilityMode, setFolderVisibilityMode] =
    createSignal<FolderVisibilityAction>("default");
const [folderOpenState, setFolderOpenState] = createSignal<Record<string, boolean>>({});
const [registeredFolders, setRegisteredFolders] =
    createSignal<Record<string, number>>({});
const [allFoldersCollapsed, setAllFoldersCollapsed] = createSignal(false);

export { allFoldersCollapsed };

function defaultFolderOpen(depth: number, mode = folderVisibilityMode()) {
    if (mode === "collapse") return false;
    if (mode === "expand") return true;
    return depth < 1;
}

function syncAllFoldersCollapsed(
    nextOpenState = folderOpenState(),
    nextRegisteredFolders = registeredFolders(),
) {
    const paths = Object.keys(nextRegisteredFolders);
    setAllFoldersCollapsed(
        paths.length > 0 && paths.every((path) => nextOpenState[path] === false),
    );
}

function syncRegisteredFolders(entries: VaultEntry[], rootDepth = 0) {
    const nextRegisteredFolders: Record<string, number> = {};

    const walk = (nodes: VaultEntry[], depth: number) => {
        for (const node of nodes) {
            if (!node.is_dir) continue;
            nextRegisteredFolders[node.relative_path] = depth;
            if (node.children?.length) {
                walk(node.children, depth + 1);
            }
        }
    };

    walk(entries, rootDepth);
    setRegisteredFolders(nextRegisteredFolders);
    setFolderOpenState((prev) => {
        const next: Record<string, boolean> = {};
        for (const [path, depth] of Object.entries(nextRegisteredFolders)) {
            next[path] = path in prev ? prev[path]! : defaultFolderOpen(depth);
        }
        syncAllFoldersCollapsed(next, nextRegisteredFolders);
        return next;
    });
}

function getFolderOpen(path: string, depth: number) {
    const current = folderOpenState();
    return path in current ? current[path]! : defaultFolderOpen(depth);
}

function setFolderOpen(path: string, depth: number, open: boolean) {
    const currentRegistered = registeredFolders();
    const nextRegistered =
        path in currentRegistered
            ? currentRegistered
            : { ...currentRegistered, [path]: depth };
    if (nextRegistered !== currentRegistered) {
        setRegisteredFolders(nextRegistered);
    }
    setFolderOpenState((prev) => {
        const next = { ...prev, [path]: open };
        syncAllFoldersCollapsed(next, nextRegistered);
        return next;
    });
    scheduleFolderStateSave();
}

export function setAllFoldersVisibility(action: "collapse" | "expand") {
    const currentRegistered = registeredFolders();
    const isOpen = action === "expand";
    setFolderVisibilityMode(action);
    setFolderOpenState(() => {
        const next = Object.fromEntries(
            Object.keys(currentRegistered).map((path) => [path, isOpen]),
        ) as Record<string, boolean>;
        syncAllFoldersCollapsed(next, currentRegistered);
        return next;
    });
    scheduleFolderStateSave();
}

export function resetFolderVisibilityState() {
    setFolderVisibilityMode("default");
    setFolderOpenState({});
    setRegisteredFolders({});
    setAllFoldersCollapsed(false);
    folderStateLoaded = false;
}

/**
 * Reveal a file in the tree: expand all ancestor folders, scroll the
 * file node into view (only if it isn't already visible), and apply a
 * short-lived highlight class so the eye can latch onto it. Used by
 * the "Show in sidebar" tab action.
 *
 * Expansion uses `setFolderOpen` for each prefix path so the persisted
 * folder-state respects the reveal. The scroll + highlight step polls
 * for the target's DOM element — necessary because the caller may have
 * just switched the sidebar FROM "outline" (or another tab) TO "files"
 * in the same tick, meaning the FileTree DOM isn't yet mounted when
 * this function runs. A fixed pair of rAFs isn't enough; Solid's
 * reactive render can take several frames to fully settle on slower
 * machines. Polling up to ~400ms gives the tree a chance to mount
 * before we measure its scroll state.
 */
export function revealFileInTree(path: string) {
    if (!path) return;
    const parts = path.split("/");
    let currentPath = "";
    for (let i = 0; i < parts.length - 1; i += 1) {
        currentPath = currentPath ? `${currentPath}/${parts[i]}` : parts[i];
        setFolderOpen(currentPath, i, true);
    }

    const selector = `[data-entry-path="${(window.CSS?.escape ?? ((v: string) => v))(path)}"]`;
    const maxAttempts = 25; // ~400ms at 16ms/frame
    let attempt = 0;

    const tryReveal = () => {
        const target = document.querySelector(selector) as HTMLElement | null;
        if (!target) {
            attempt += 1;
            if (attempt < maxAttempts) {
                window.setTimeout(tryReveal, 16);
            }
            return;
        }

        // Wait for the ancestor to report a non-zero scroll height
        // too — when the tree has only JUST mounted, its scrollable
        // ancestor still has scrollHeight === clientHeight === 0 and
        // any visibility math computed now would be wrong. Retry
        // once per frame until layout settles.
        const scrollAncestor = findScrollableAncestor(target);
        if (
            scrollAncestor &&
            scrollAncestor.clientHeight === 0 &&
            attempt < maxAttempts
        ) {
            attempt += 1;
            window.setTimeout(tryReveal, 16);
            return;
        }

        // Only scroll when the file row isn't already visible in its
        // nearest scrollable ancestor. A small safety margin (8px on
        // each side) keeps rows that are right against the top /
        // bottom edge from being judged visible-but-clipped. If the
        // row is fully visible we skip the scroll entirely so the
        // user's current scroll position is preserved — only the
        // highlight runs.
        let needsScroll = true;
        if (scrollAncestor) {
            const ancestorRect = scrollAncestor.getBoundingClientRect();
            const targetRect = target.getBoundingClientRect();
            const margin = 8;
            const fullyVisible =
                targetRect.top >= ancestorRect.top + margin &&
                targetRect.bottom <= ancestorRect.bottom - margin;
            if (fullyVisible) needsScroll = false;
        }

        if (needsScroll) {
            try {
                target.scrollIntoView({ behavior: "smooth", block: "center" });
            } catch {
                target.scrollIntoView();
            }
        }
        target.classList.remove("mz-file-tree-reveal-highlight");
        void target.offsetWidth;
        target.classList.add("mz-file-tree-reveal-highlight");
        window.setTimeout(() => {
            target.classList.remove("mz-file-tree-reveal-highlight");
        }, 1500);
    };

    // Kick off on the next frame so Solid has committed any pending
    // sidebar-tab swap (Outline → Files) before we start looking for
    // the tree DOM.
    requestAnimationFrame(() => {
        requestAnimationFrame(tryReveal);
    });
}

/**
 * Walk ancestors looking for the first element whose `overflow-y`
 * allows scrolling and whose scrollHeight actually exceeds its
 * clientHeight. Returns null if no such ancestor exists (e.g. the
 * tree fits entirely in its container and no scrolling is needed).
 */
function findScrollableAncestor(el: HTMLElement): HTMLElement | null {
    let current: HTMLElement | null = el.parentElement;
    while (current) {
        const overflowY = getComputedStyle(current).overflowY;
        const scrollable = overflowY === "auto" || overflowY === "scroll" || overflowY === "overlay";
        if (scrollable && current.scrollHeight > current.clientHeight) {
            return current;
        }
        current = current.parentElement;
    }
    return null;
}

// ---------------------------------------------------------------------------
// Inline rename state (module-level so FileItem / FolderItem can access it)
// ---------------------------------------------------------------------------

const [renamingPath, setRenamingPath] = createSignal<string | null>(null);
const [renamingName, setRenamingName] = createSignal("");
let _renameHiddenSuffix: string | null = null;
let _renameOriginalDisplay = "";
let _renameIsDir = false;

/** Start inline rename for a file/folder entry */
function startInlineRename(path: string, isDir: boolean) {
    const name = path.split("/").pop() || path;
    const hiddenSuffixes = [".markdown", ".md", ".mindzj"];
    const lower = name.toLowerCase();
    _renameIsDir = isDir;
    _renameHiddenSuffix = isDir
        ? null
        : hiddenSuffixes.find((s) => lower.endsWith(s)) ?? null;
    _renameOriginalDisplay = _renameHiddenSuffix
        ? name.slice(0, -_renameHiddenSuffix.length)
        : name;
    setRenamingName(_renameOriginalDisplay);
    setRenamingPath(path);
}

/**
 * Move an entry on disk while migrating every open editor path. Auto-save is
 * paused first so a write racing the move cannot recreate the source file.
 */
async function moveEntryAndSync(oldPath: string, newPath: string, isDir: boolean) {
    const affectedPaths = isDir
        ? vaultStore.openFiles()
            .map((file) => file.path)
            .filter((path) => path === oldPath || path.startsWith(`${oldPath}/`))
        : [oldPath];
    const uniqueAffectedPaths = [...new Set(affectedPaths)];

    for (const path of uniqueAffectedPaths) editorStore.pauseAutoSave(path);

    let moved = false;
    let migratedPaths: string[] = [];
    try {
        // Persist edits made before the drag. Later keystrokes remain buffered
        // until their editor state has been assigned to the destination path.
        await Promise.all(
            uniqueAffectedPaths.map((path) => editorStore.flushPendingSave(path)),
        );

        // Snapshot backlinks before rename_file clears the old index entry.
        const backlinks = isDir ? [] : await fetchBacklinks(oldPath);
        await invoke("rename_file", { from: oldPath, to: newPath });
        moved = true;

        migratedPaths = uniqueAffectedPaths.map((path) =>
            remapMovedPath(path, oldPath, newPath, isDir),
        );
        vaultStore.renameFilePath(oldPath, newPath, isDir);
        uniqueAffectedPaths.forEach((path, index) => {
            editorStore.renameFileState(path, migratedPaths[index]!);
        });

        // Persist edits made while rename_file was running to the new path.
        for (const path of migratedPaths) editorStore.resumeAutoSave(path);
        await Promise.all(
            migratedPaths.map((path) => editorStore.flushPendingSave(path)),
        );

        if (!isDir) {
            await updateBacklinksOnFileRename(oldPath, newPath, backlinks);
        }
    } catch (error) {
        const pathsToResume = moved ? migratedPaths : uniqueAffectedPaths;
        for (const path of pathsToResume) editorStore.resumeAutoSave(path);
        throw error;
    }
}

/** Confirm rename — called on Enter or blur */
async function confirmRename() {
    const path = renamingPath();
    if (!path) return;

    const entered = renamingName().trim();
    setRenamingPath(null); // close the input immediately

    if (!entered || entered === _renameOriginalDisplay) return;

    const name = path.split("/").pop() || path;
    const newName =
        _renameHiddenSuffix && !entered.toLowerCase().endsWith(_renameHiddenSuffix)
            ? `${entered}${_renameHiddenSuffix}`
            : entered;
    if (newName === name) return;

    const dir = path.split("/").slice(0, -1).join("/");
    const newPath = dir ? `${dir}/${newName}` : newName;

    try {
        const nextFileOrder = await buildFileOrderAfterRename(path, newPath, _renameIsDir);
        await moveEntryAndSync(path, newPath, _renameIsDir);

        // Preserve the visible default-order slot for this entry.
        if (nextFileOrder) {
            await saveFileOrder(nextFileOrder);
        }

        await vaultStore.refreshFileTree();
    } catch (e) {
        console.error("Rename failed:", e);
    }
}

/** Cancel rename — called on Escape */
function cancelRename() {
    setRenamingPath(null);
}

