export const FileTree: Component<FileTreeProps> = (props) => {
    let resourceInput: HTMLInputElement | undefined;
    const [resourceTargetDir, setResourceTargetDir] = createSignal("");
    const [menu, setMenu] = createSignal<{ show: boolean; x: number; y: number; items: MenuItem[] }>({
        show: false, x: 0, y: 0, items: [],
    });
    const [fileProperties, setFileProperties] = createSignal<{
        path: string;
        metadata: FileMetadata;
    } | null>(null);

    const formatDateTime = (value: string) => {
        const date = new Date(value);
        if (Number.isNaN(date.getTime())) return value;
        const pad = (part: number) => String(part).padStart(2, "0");
        return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
    };

    const formatFileSize = (bytes: number) => {
        if (bytes < 1024) return `${bytes} B`;
        const units = ["KB", "MB", "GB", "TB"];
        let value = bytes / 1024;
        let unit = 0;
        while (value >= 1024 && unit < units.length - 1) {
            value /= 1024;
            unit += 1;
        }
        return `${value.toFixed(value >= 10 ? 1 : 2)} ${units[unit]} (${bytes} B)`;
    };

    async function showFileProperties(path: string) {
        try {
            const metadata = await invoke<FileMetadata>("get_file_metadata", {
                relativePath: path,
            });
            setFileProperties({ path, metadata });
        } catch (error) {
            console.error("Failed to read file properties:", error);
        }
    }

    const sortMode = () => props.sortMode ?? "custom";
    const sortOrder = () => props.sortOrder ?? "asc";
    const dirPath = () => {
        // Root level
        if (!props.depth || props.depth === 0) return "";
        // For nested levels, we need the parent dir path - derived from first entry
        const first = props.entries[0];
        if (!first) return "";
        return getParentDir(first.relative_path);
    };
    const sortedEntries = () => sortEntries(props.entries, sortMode(), sortOrder(), dirPath());

    // Install global drag tracking once & load persisted state
    installGlobalDragTracking();
    onMount(async () => {
        await loadFolderState();
        loadFileOrder();
    });

    createEffect(() => {
        if ((props.depth ?? 0) !== 0) return;
        syncRegisteredFolders(props.entries, props.depth ?? 0);
    });

    async function showInExplorer(path: string) {
        try {
            await invoke("reveal_in_file_manager", { relativePath: path });
        } catch (e) {
            console.error("Open in file manager failed:", e);
            navigator.clipboard.writeText(path).catch(() => {});
        }
    }

    function addResourcesTo(dirPath: string) {
        setResourceTargetDir(dirPath);
        if (resourceInput) {
            resourceInput.value = "";
            resourceInput.click();
        }
    }

    async function importSelectedResources(files: FileList | null) {
        if (!files?.length) return;
        const paths = new Set<string>();
        const collectPaths = (entries: VaultEntry[]) => {
            for (const entry of entries) {
                paths.add(entry.relative_path);
                if (entry.children) collectPaths(entry.children);
            }
        };
        collectPaths(vaultStore.fileTree());
        const dirPath = resourceTargetDir();
        for (const file of Array.from(files)) {
            const baseName = file.name.split(/[\\/]/).pop()?.replace(/[\x00-\x1f]/g, "").trim();
            if (!baseName || baseName === "." || baseName === "..") continue;
            const dot = baseName.lastIndexOf(".");
            const stem = dot > 0 ? baseName.slice(0, dot) : baseName;
            const extension = dot > 0 ? baseName.slice(dot) : "";
            let candidate = dirPath ? `${dirPath}/${baseName}` : baseName;
            let suffix = 2;
            while (paths.has(candidate)) {
                const name = `${stem} (${suffix++})${extension}`;
                candidate = dirPath ? `${dirPath}/${name}` : name;
            }
            try {
                const bytes = new Uint8Array(await file.arrayBuffer());
                let binary = "";
                const chunkSize = 0x8000;
                for (let offset = 0; offset < bytes.length; offset += chunkSize) {
                    binary += String.fromCharCode(...bytes.subarray(offset, offset + chunkSize));
                }
                await invoke("write_binary_file", { relativePath: candidate, base64Data: btoa(binary) });
                paths.add(candidate);
            } catch (error) {
                console.error(`Failed to import resource ${file.name}:`, error);
            }
        }
        await vaultStore.refreshFileTree();
    }

    async function downloadResource(path: string) {
        try {
            const root = vaultStore.vaultInfo()?.path ?? "";
            const response = await fetch(toVaultAssetUrl(root, path));
            if (!response.ok) throw new Error(`Download failed: ${response.status}`);
            const url = URL.createObjectURL(await response.blob());
            const anchor = document.createElement("a");
            anchor.href = url;
            anchor.download = path.split(/[\\/]/).pop() ?? "download";
            anchor.click();
            window.setTimeout(() => URL.revokeObjectURL(url), 1000);
        } catch (error) {
            console.error("Failed to download resource:", error);
        }
    }

    /** Reusable rename trigger — activates inline rename input */
    function renameEntry(path: string, isDir: boolean) {
        startInlineRename(path, isDir);
    }

    // Listen for global F2 rename event from App.tsx
    onMount(() => {
        const handleRenameEvent = () => {
            const active = props.activePath;
            if (!active) return;
            const entry = props.entries.find((en) => en.relative_path === active);
            renameEntry(active, entry?.is_dir ?? false);
        };
        document.addEventListener("mindzj:rename-active-file", handleRenameEvent);
        onCleanup(() => document.removeEventListener("mindzj:rename-active-file", handleRenameEvent));
    });

    function showContextForFile(e: MouseEvent, path: string, isDir: boolean) {
        e.preventDefault();
        e.stopPropagation();
        const dirPath = isDir ? path : path.split("/").slice(0, -1).join("/") || "";
        const name = path.split("/").pop() ?? path;
        const items: MenuItem[] = [];
        if (!isDir) {
            items.push({ label: t("context.open"), icon: "\uD83D\uDCC4", action: () => { void openFileRouted(path); } });
            const extension = name.split(".").pop()?.toLowerCase();
            if ((extension === "html" || extension === "htm") && isMarkdownPath(vaultStore.activeFile()?.path ?? "")) {
                items.push({
                    label: t("context.insertHtmlEmbed"),
                    icon: "🌐",
                    action: () => {
                        document.dispatchEvent(new CustomEvent("mindzj:insert-text", {
                            detail: { text: `![[/${path}]]` },
                        }));
                    },
                });
            }
        }
        items.push({
            label: t("context.newNote"), icon: "\u270F\uFE0F",
            action: async () => {
                const n = await promptDialog(t("fileTree.noteNamePrompt"), t("fileTree.newNoteDefault"));
                if (!n) return;
                const fileName = n.endsWith(".md") ? n : `${n}.md`;
                const p = dirPath ? `${dirPath}/${fileName}` : fileName;
                await vaultStore.createFile(p, "");
                await vaultStore.openFile(p);
            },
        });
        items.push({
            label: t("context.newFolder"), icon: "\uD83D\uDCC1",
            action: async () => { const n = await promptDialog(t("fileTree.folderNamePrompt")); if (n) await vaultStore.createDir(dirPath ? `${dirPath}/${n}` : n); },
        });
        items.push({
            label: t("context.addResource"), icon: "＋", separator: true,
            action: () => addResourcesTo(dirPath),
        });
        items.push({
            label: t("context.newMindMap"), icon: "\uD83D\uDDFA\uFE0F", separator: true,
            action: async () => {
                const n = await promptDialog(t("fileTree.mindzjFileNamePrompt"), t("fileTree.newMindzjDefault"));
                if (!n) return;
                const fileName = n.endsWith(".mindzj") ? n : `${n}.mindzj`;
                const p = dirPath ? `${dirPath}/${fileName}` : fileName;
                await vaultStore.createFile(p, `{"type":"mindzj","version":"0.1.0","nodes":[],"edges":[]}`);
                await vaultStore.openFile(p);
            },
        });
        items.push({
            label: t("context.rename"), icon: "\u270E", separator: true,
            action: () => renameEntry(path, isDir),
        });
        items.push({ label: t("context.showInExplorer"), icon: "\uD83D\uDCC2", action: () => showInExplorer(path) });
        if (!isDir) {
            items.push({ label: t("context.download"), icon: "\u2B07", action: () => { void downloadResource(path); } });
            items.push({
                label: t("context.properties"),
                icon: "ⓘ",
                action: () => { void showFileProperties(path); },
            });
        }
        if (!isDir && props.onExportPdf && isMarkdownPath(path)) {
            items.push({
                label: t("context.exportPdf"),
                icon: "\uD83D\uDCD9",
                separator: true,
                action: () => props.onExportPdf?.(path),
            });
        }
        if (!isDir && props.onOpenSplit) {
            items.push({
                label: t("context.splitRight"),
                icon: ">",
                separator: !props.onExportPdf || !isMarkdownPath(path),
                action: () => { void props.onOpenSplit?.(path, "right"); },
            });
            items.push({
                label: t("context.splitLeft"),
                icon: "<",
                action: () => { void props.onOpenSplit?.(path, "left"); },
            });
        }
        items.push({
            label: t("context.delete"), icon: "\uD83D\uDDD1", danger: true, separator: true,
            action: async () => {
                const yes = await confirmDialog(t("fileTree.deleteConfirm", { name }));
                if (!yes) return;
                if (isDir) {
                    await vaultStore.deleteDir(path);
                    editorStore.removeFileState(path, true);
                    return;
                }
                await vaultStore.deleteFile(path);
                editorStore.removeFileState(path, false);
            },
        });
        setMenu({ show: true, x: e.clientX, y: e.clientY, items });
    }

    function showContextForEmpty(e: MouseEvent) {
        e.preventDefault();
        setMenu({
            show: true, x: e.clientX, y: e.clientY,
            items: [
                { label: t("context.newNote"), icon: "\u270F\uFE0F", action: async () => {
                    const n = await promptDialog(t("fileTree.noteNamePrompt"), t("fileTree.newNoteDefault"));
                if (!n) return;
                const fileName = n.endsWith(".md") ? n : `${n}.md`;
                    await vaultStore.createFile(fileName, "");
                    await vaultStore.openFile(fileName);
                }},
                { label: t("context.newFolder"), icon: "\uD83D\uDCC1", action: async () => { const n = await promptDialog(t("fileTree.folderNamePrompt")); if (n) await vaultStore.createDir(n); }},
                { label: t("context.addResource"), icon: "＋", separator: true, action: () => addResourcesTo("") },
                { label: t("context.newMindMap"), icon: "\uD83D\uDDFA\uFE0F", action: async () => {
                    const n = await promptDialog(t("fileTree.mindzjFileNamePrompt"), t("fileTree.newMindzjDefault"));
                    if (!n) return;
                    const fileName = n.endsWith(".mindzj") ? n : `${n}.mindzj`;
                    await vaultStore.createFile(fileName, `{"type":"mindzj","version":"0.1.0","nodes":[],"edges":[]}`);
                    // Open the newly-created file so it is both the
                    // active file (highlighted in the tree) and shown
                    // in the editor area. The new-note (.md) branch
                    // above does the same thing.
                    await vaultStore.openFile(fileName);
                }},
            ],
        });
    }

    return (
        <div
            data-drop-path=""
            style={{ "user-select": "none", "min-height": "100%", position: "relative" }}
            onContextMenu={showContextForEmpty}
        >
            <input
                ref={resourceInput}
                type="file"
                multiple
                style={{ display: "none" }}
                onChange={(event) => { void importSelectedResources(event.currentTarget.files); }}
            />
            <For each={sortedEntries()}>
                {(entry) => (
                    <Show
                        when={entry.is_dir}
                        fallback={
                            <FileItem
                                entry={entry}
                                onClick={() => props.onFileClick(entry.relative_path)}
                                onContextMenu={(e) => showContextForFile(e, entry.relative_path, false)}
                                isActive={props.activePath === entry.relative_path}
                                depth={props.depth ?? 0}
                            />
                        }>
                        <FolderItem
                            entry={entry}
                            onFileClick={props.onFileClick}
                            onOpenSplit={props.onOpenSplit}
                            onExportPdf={props.onExportPdf}
                            onContextMenu={(e) => showContextForFile(e, entry.relative_path, true)}
                            activePath={props.activePath}
                            depth={props.depth ?? 0}
                            sortMode={sortMode()}
                            sortOrder={sortOrder()}
                        />
                    </Show>
                )}
            </For>
            <Show when={menu().show}>
                <ContextMenu
                    x={menu().x} y={menu().y} items={menu().items}
                    onClose={() => setMenu((p) => ({ ...p, show: false }))}
                />
            </Show>
            <Show when={fileProperties()}>
                {(properties) => (
                    <div
                        role="presentation"
                        onMouseDown={(event) => {
                            if (event.target === event.currentTarget) setFileProperties(null);
                        }}
                        style={{
                            position: "fixed",
                            inset: "0",
                            display: "flex",
                            "align-items": "center",
                            "justify-content": "center",
                            background: "rgba(0, 0, 0, 0.45)",
                            "z-index": "10020",
                        }}
                    >
                        <div
                            role="dialog"
                            aria-modal="true"
                            aria-label={t("fileProperties.title")}
                            style={{
                                width: "min(420px, calc(100vw - 32px))",
                                background: "var(--mz-bg-secondary)",
                                color: "var(--mz-text-primary)",
                                border: "1px solid var(--mz-border-strong)",
                                "border-radius": "var(--mz-radius-lg, 8px)",
                                "box-shadow": "0 14px 44px rgba(0,0,0,0.38)",
                                padding: "18px",
                                "user-select": "text",
                            }}
                            onMouseDown={(event) => event.stopPropagation()}
                        >
                            <div style={{ display: "flex", "align-items": "center", gap: "10px", "margin-bottom": "16px" }}>
                                <strong style={{ flex: "1", "font-size": "var(--mz-font-size-md)" }}>{t("fileProperties.title")}</strong>
                                <button
                                    onClick={() => setFileProperties(null)}
                                    aria-label={t("common.close")}
                                    style={{ border: "none", background: "transparent", color: "var(--mz-text-muted)", cursor: "pointer", "font-size": "18px" }}
                                >×</button>
                            </div>
                            <div style={{ "margin-bottom": "14px", "font-weight": "600", "word-break": "break-all" }}>
                                {properties().path.split("/").pop() ?? properties().path}
                            </div>
                            <div style={{ display: "grid", "grid-template-columns": "110px minmax(0, 1fr)", gap: "10px 14px", "font-size": "var(--mz-font-size-sm)" }}>
                                <span style={{ color: "var(--mz-text-muted)" }}>{t("fileProperties.size")}</span>
                                <span>{formatFileSize(properties().metadata.size)}</span>
                                <span style={{ color: "var(--mz-text-muted)" }}>{t("fileProperties.created")}</span>
                                <span>{formatDateTime(properties().metadata.created)}</span>
                            </div>
                        </div>
                    </div>
                )}
            </Show>
        </div>
    );
};

// ---------------------------------------------------------------------------
// Folder item with mouse-based drag
// ---------------------------------------------------------------------------

const FolderItem: Component<{
    entry: VaultEntry;
    onFileClick: (p: string) => void;
    onOpenSplit?: (path: string, direction: FileTreeSplitDirection) => void | Promise<void>;
    onExportPdf?: (path: string) => void;
    onContextMenu: (e: MouseEvent) => void;
    activePath: string | null;
    depth: number;
    sortMode: SortMode;
    sortOrder: SortOrder;
}> = (props) => {
    const isOpen = () => getFolderOpen(props.entry.relative_path, props.depth);
    const pad = () => `${12 + props.depth * 16}px`;

    return (
        <div style={{ position: "relative" }}>
            <div
                data-entry-path={props.entry.relative_path}
                data-entry-is-dir="true"
                data-drop-path={props.entry.relative_path}
                onMouseDown={(e) => {
                    if (e.button === 0) startDrag(e, props.entry.relative_path, true, props.entry.name, e.currentTarget);
                }}
                onClick={() =>
                    setFolderOpen(props.entry.relative_path, props.depth, !isOpen())
                }
                onContextMenu={props.onContextMenu}
                style={{
                    display: "flex",
                    "align-items": "center",
                    gap: "4px",
                    padding: `3px 8px 3px ${pad()}`,
                    cursor: "pointer",
                    "font-size": "var(--mz-font-size-sm)",
                    color: "var(--mz-text-secondary)",
                    "border-radius": "var(--mz-radius-sm)",
                    transition: "background 80ms",
                }}
                onMouseEnter={(e) => { if (!dragSource()) e.currentTarget.style.background = "var(--mz-bg-hover)"; }}
                onMouseLeave={(e) => { if (!dragSource()) e.currentTarget.style.background = ""; }}
            >
                <svg width="12" height="12" viewBox="0 0 12 12" fill="none"
                    style={{ transform: isOpen() ? "rotate(90deg)" : "rotate(0deg)", transition: "transform 150ms", "flex-shrink": "0", "pointer-events": "none" }}>
                    <path d="M4 2.5L7.5 6L4 9.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" />
                </svg>
                <svg width="14" height="14" viewBox="0 0 16 16" fill="none" style={{ "flex-shrink": "0", "pointer-events": "none" }}>
                    <path d="M2 4.5C2 3.67 2.67 3 3.5 3H6.17a1.5 1.5 0 011.06.44L8.5 4.7a.5.5 0 00.35.15H12.5c.83 0 1.5.67 1.5 1.5v5.15c0 .83-.67 1.5-1.5 1.5h-9A1.5 1.5 0 012 11.5V4.5z"
                        fill={isOpen() ? "var(--mz-accent)" : "var(--mz-text-muted)"} opacity={isOpen() ? "0.7" : "0.5"} />
                </svg>
                <Show when={renamingPath() === props.entry.relative_path}
                    fallback={
                        <span style={{ overflow: "hidden", "text-overflow": "ellipsis", "white-space": "nowrap", "pointer-events": "none" }}>
                            {props.entry.name}
                        </span>
                    }>
                    <input
                        ref={(el) => { setTimeout(() => { el.focus(); el.select(); }, 0); }}
                        value={renamingName()}
                        onInput={(e) => setRenamingName(e.currentTarget.value)}
                        onKeyDown={(e) => {
                            e.stopPropagation();
                            if (e.key === "Enter") { e.preventDefault(); confirmRename(); }
                            if (e.key === "Escape") { e.preventDefault(); cancelRename(); }
                        }}
                        onBlur={() => confirmRename()}
                        onClick={(e) => e.stopPropagation()}
                        onMouseDown={(e) => e.stopPropagation()}
                        style={{
                            flex: "1",
                            "min-width": "0",
                            background: "var(--mz-bg-primary)",
                            color: "var(--mz-text-primary)",
                            border: "1px solid var(--mz-accent)",
                            "border-radius": "var(--mz-radius-sm)",
                            padding: "0 4px",
                            "font-size": "inherit",
                            "font-family": "inherit",
                            outline: "none",
                        }}
                    />
                </Show>
            </div>
            <Show when={isOpen() && props.entry.children}>
                <FileTree
                    entries={props.entry.children!}
                    onFileClick={props.onFileClick}
                    onOpenSplit={props.onOpenSplit}
                    onExportPdf={props.onExportPdf}
                    activePath={props.activePath}
                    depth={props.depth + 1}
                    sortMode={props.sortMode}
                    sortOrder={props.sortOrder}
                />
            </Show>
        </div>
    );
};

// ---------------------------------------------------------------------------
// File item with mouse-based drag
// ---------------------------------------------------------------------------

const FileItem: Component<{
    entry: VaultEntry;
    onClick: () => void;
    onContextMenu: (e: MouseEvent) => void;
    isActive: boolean;
    depth: number;
}> = (props) => {
    const pad = () => `${28 + props.depth * 16}px`;
    const isMindZJ = () => props.entry.extension === "mindzj";
    const fileBadge = () => getFileBadge(props.entry.extension);

    return (
        <div
            data-entry-path={props.entry.relative_path}
            data-entry-is-dir="false"
            onMouseDown={(e) => {
                if (e.button === 0) startDrag(e, props.entry.relative_path, false, props.entry.name, e.currentTarget);
            }}
            onClick={props.onClick}
            onContextMenu={props.onContextMenu}
            style={{
                display: "flex",
                "align-items": "center",
                gap: "6px",
                padding: `3px 8px 3px ${pad()}`,
                cursor: "pointer",
                "font-size": "var(--mz-font-size-sm)",
                color: props.isActive ? "var(--mz-text-primary)" : "var(--mz-text-secondary)",
                background: props.isActive ? "var(--mz-bg-active)" : "transparent",
                "border-radius": "var(--mz-radius-sm)",
                transition: "background 80ms",
            }}
            onMouseEnter={(e) => { if (!props.isActive && !dragSource()) e.currentTarget.style.background = "var(--mz-bg-hover)"; }}
            onMouseLeave={(e) => { if (!props.isActive && !dragSource()) e.currentTarget.style.background = ""; }}
        >
            <Show
                when={isMindZJ()}
                fallback={
                    <svg width="14" height="14" viewBox="0 0 16 16" fill="none" style={{ "flex-shrink": "0", "pointer-events": "none" }}>
                        <path d="M4 1.5h5.586a1 1 0 01.707.293l2.914 2.914a1 1 0 01.293.707V13.5a1 1 0 01-1 1H4a1 1 0 01-1-1v-11a1 1 0 011-1z" stroke={fileBadge().color} stroke-width="1" fill="none" />
                        <path d="M9.5 1.5V5h3.5" stroke={fileBadge().color} stroke-width="1" fill="none" />
                    </svg>
                }
            >
                <svg width="15" height="15" viewBox="0 0 16 16" fill="none" style={{ "flex-shrink": "0", "pointer-events": "none" }}>
                    <path d="M5 8h3M8 8V4.5M8 8v3.5M8 4.5h2M8 11.5h2" stroke="var(--mz-success)" stroke-width="1.2" stroke-linecap="round" />
                    <rect x="1.5" y="6" width="3.5" height="4" rx="1" stroke="var(--mz-success)" stroke-width="1.2" />
                    <rect x="10" y="2.5" width="4.5" height="4" rx="1" stroke="var(--mz-success)" stroke-width="1.2" />
                    <rect x="10" y="9.5" width="4.5" height="4" rx="1" stroke="var(--mz-success)" stroke-width="1.2" />
                </svg>
            </Show>
            <Show when={renamingPath() === props.entry.relative_path}
                fallback={
                    <>
                        <span style={{ overflow: "hidden", "text-overflow": "ellipsis", "white-space": "nowrap", flex: "1", "pointer-events": "none" }}>
                            {displayName(props.entry.name)}
                        </span>
                        <Show when={isMindZJ()}>
                            <span style={{ "font-size": "9px", color: "var(--mz-text-muted)", "flex-shrink": "0", "text-transform": "uppercase", "font-weight": "600", "letter-spacing": "0.5px", "pointer-events": "none" }}>
                                MINDZJ
                            </span>
                        </Show>
                        <Show when={fileBadge().label}>
                            <span style={{ "font-size": "8px", color: fileBadge().color, background: fileBadge().background, "flex-shrink": "0", "font-weight": "700", "letter-spacing": "0.2px", "pointer-events": "none", padding: "1px 3px", "border-radius": "3px" }}>
                                {fileBadge().label}
                            </span>
                        </Show>
                    </>
                }>
                <input
                    ref={(el) => { setTimeout(() => { el.focus(); el.select(); }, 0); }}
                    value={renamingName()}
                    onInput={(e) => setRenamingName(e.currentTarget.value)}
                    onKeyDown={(e) => {
                        e.stopPropagation();
                        if (e.key === "Enter") { e.preventDefault(); confirmRename(); }
                        if (e.key === "Escape") { e.preventDefault(); cancelRename(); }
                    }}
                    onBlur={() => confirmRename()}
                    onClick={(e) => e.stopPropagation()}
                    onMouseDown={(e) => e.stopPropagation()}
                    style={{
                        flex: "1",
                        "min-width": "0",
                        background: "var(--mz-bg-primary)",
                        color: "var(--mz-text-primary)",
                        border: "1px solid var(--mz-accent)",
                        "border-radius": "var(--mz-radius-sm)",
                        padding: "0 4px",
                        "font-size": "inherit",
                        "font-family": "inherit",
                        outline: "none",
                    }}
                />
            </Show>
        </div>
    );
};
