/** Inline image preview widget */
class ImageWidget extends WidgetType {
    constructor(
        private src: string,
        private alt: string,
        private vaultRoot: string,
        private currentFilePath: string,
    ) {
        super();
    }

    toDOM(view: EditorView): HTMLElement {
        // Parse the `|width` or `|widthxheight` suffix out of the
        // alt text so (a) the displayed alt text is clean and (b)
        // we can apply the persisted display size. The raw alt
        // (including suffix) is still kept in `this.alt` so the
        // wheel-zoom onResize below can find the original string
        // to rewrite.
        const { altText, width, height } = parseImageSize(this.alt);

        const wrapper = document.createElement("div");
        wrapper.className = "mz-lp-image image-embed internal-embed is-loaded";
        wrapper.setAttribute("src", this.src);
        wrapper.setAttribute("alt", altText);
        wrapper.style.cssText =
            "padding: 8px 0; max-width: 100%; cursor: pointer;";

        const img = document.createElement("img");
        // data-src = raw vault-relative path from markdown (used by plugins like pixel-perfect-image)
        img.setAttribute("data-src", this.src);
        img.src = resolveImageAssetUrl(
            this.src,
            this.vaultRoot,
            this.currentFilePath,
        );
        img.alt = altText;
        img.className = "mz-embed-image";
        // Do NOT set max-width/max-height inline — use CSS class instead.
        // This allows plugins (pixel-perfect-image) to freely resize via inline style.width.
        img.style.cssText = "border-radius: 6px; display: block;";
        // Apply persisted display size from the markdown alt. We
        // set the width BEFORE the image finishes loading so there's
        // no reflow jitter when the natural size comes in.
        if (width != null) {
            img.style.width = `${width}px`;
            img.style.height = height != null ? `${height}px` : "auto";
            img.setAttribute("data-ppi-wheel-inline-width", String(width));
        }
        img.onerror = () => {
            img.style.display = "none";
            const fallback = document.createElement("span");
            fallback.textContent = `[${t("livePreview.imageFallback")}: ${altText || this.src}]`;
            fallback.style.cssText =
                "color: var(--mz-text-muted); font-size: 12px; font-style: italic;";
            wrapper.appendChild(fallback);
        };

        wrapper.appendChild(img);

        // Build a source-rewriter closure used by both wheel zoom
        // and right-click resize presets. On a size change it:
        //  1. Finds the image's current source position via
        //     `view.posAtDOM(img)` (robust to stale widgets — we
        //     always ask CM6 where this DOM node now lives in the
        //     document, so inserts/deletes elsewhere don't shift
        //     the target out from under us).
        //  2. Scans the line for the `![...](...)` whose src
        //     matches this widget's src (disambiguates when
        //     multiple images are on the same line).
        //  3. Dispatches a CM6 change replacing the match with
        //     the new `![alt|newWidth](src)`.
        // The widget will be rebuilt automatically on the next
        // build-decorations pass because `eq()` now includes alt,
        // so CM6 re-creates the DOM with the new parsed size.
        const persistSize = (newWidth: number) => {
            try {
                const pos = view.posAtDOM(img);
                if (pos < 0) return;
                const line = view.state.doc.lineAt(pos);
                const lineText = line.text;
                const imgRegex = /!\[([^\]]*)\]\(([^)]+)\)/g;
                let m: RegExpExecArray | null;
                while ((m = imgRegex.exec(lineText)) !== null) {
                    if (m[2] !== this.src) continue;
                    const mStart = line.from + m.index;
                    const mEnd = mStart + m[0].length;
                    // Only rewrite the FIRST match with this src on
                    // the line that actually overlaps this widget's
                    // current position. If the same image appears
                    // multiple times on the line, the position lookup
                    // picks out the specific occurrence.
                    if (pos < mStart || pos > mEnd) continue;
                    const currentAltText = parseImageSize(m[1]).altText;
                    const newAlt = formatImageAlt(
                        currentAltText,
                        newWidth,
                        null,
                    );
                    const newMd = `![${newAlt}](${this.src})`;
                    if (newMd === m[0]) return;
                    view.dispatch({
                        changes: { from: mStart, to: mEnd, insert: newMd },
                    });
                    return;
                }
            } catch (err) {
                // eslint-disable-next-line no-console
                console.warn("[image-resize] persist failed:", err);
            }
        };

        // Alt+wheel zoom & Ctrl+click
        attachWheelZoom(img, { onResize: persistSize });
        attachCtrlClick(img, this.src, this.currentFilePath);

        // Right-click context menu for image operations. Pass the
        // same `persistSize` callback so that picking a size preset
        // from the menu also writes back to the markdown source
        // (not just the live wheel-zoom path).
        wrapper.addEventListener("contextmenu", (e) => {
            e.preventDefault();
            e.stopPropagation();
            showImageContextMenu(
                e,
                this.src,
                this.currentFilePath,
                img,
                persistSize,
            );
        });

        return wrapper;
    }

    eq(other: ImageWidget): boolean {
        // IMPORTANT: include `alt` in the equality check so CM6
        // rebuilds the widget when the alt (and therefore the
        // parsed size) changes. Without this, a wheel-zoom that
        // rewrites the markdown source would leave the old widget
        // in place with its pre-zoom size, and CM6 would only
        // refresh on the next unrelated edit.
        return this.src === other.src && this.alt === other.alt;
    }
}

/** Sandboxed inline preview for an embedded local HTML resource. */
class HtmlEmbedWidget extends WidgetType {
    constructor(private path: string, private vaultRoot: string) { super(); }

    toDOM(): HTMLElement {
        const wrapper = document.createElement("div");
        wrapper.className = "mz-lp-html-embed";
        const iframe = document.createElement("iframe");
        iframe.src = toVaultAssetUrl(this.vaultRoot, this.path.replace(/^\//, ""));
        iframe.title = this.path.split("/").pop() || "HTML page";
        iframe.loading = "lazy";
        iframe.referrerPolicy = "no-referrer";
        iframe.setAttribute("sandbox", "allow-scripts allow-forms allow-popups allow-downloads");
        wrapper.appendChild(iframe);
        return wrapper;
    }

    eq(other: HtmlEmbedWidget): boolean {
        return this.path === other.path && this.vaultRoot === other.vaultRoot;
    }
}

/** Interactive checkbox widget for task lists */
class CheckboxWidget extends WidgetType {
    constructor(private checked: boolean) {
        super();
    }

    toDOM(view: EditorView): HTMLElement {
        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = this.checked;
        cb.className = "mz-lp-checkbox";

        cb.addEventListener("click", (e) => {
            e.preventDefault();
            // Find position and toggle the checkbox in the document
            const pos = view.posAtDOM(cb);
            const line = view.state.doc.lineAt(pos);
            const lineText = line.text;
            const newText = this.checked
                ? lineText.replace("- [x]", "- [ ]").replace("- [X]", "- [ ]")
                : lineText.replace("- [ ]", "- [x]");
            view.dispatch({
                changes: { from: line.from, to: line.to, insert: newText },
            });
        });

        return cb;
    }

    eq(other: CheckboxWidget): boolean {
        return this.checked === other.checked;
    }
}

/**
 * Tiny widget that renders the unordered-list marker (`-`, `*`, `+`) as
 * a round bullet. Inline (non-block) replace, so CM6 doesn't treat it
 * as atomic — arrow keys can move normally through the line.
 */
class BulletWidget extends WidgetType {
    toDOM(): HTMLElement {
        const anchor = document.createElement("span");
        anchor.className = "mz-lp-bullet-anchor";
        const dot = document.createElement("span");
        dot.className = "mz-lp-bullet";
        anchor.appendChild(dot);
        return anchor;
    }
    eq(): boolean {
        return true;
    }
}
const bulletWidget = new BulletWidget();

// ---------------------------------------------------------------------------
// Decoration builders
// ---------------------------------------------------------------------------

/**
 * Hide syntax markers (**, __, ~~, %%, [, ](url), etc.) via a MARK
 * decoration with CSS that collapses them to zero visual width.
 *
 * Previous approach used `Decoration.replace({})` which REMOVED the
 * characters from the DOM entirely. That caused two problems:
 *   1. CM6's `posAtCoords` lost positional accuracy because the
 *      replaced range was an atomic gap in the DOM — clicks on styled
 *      text near a hidden marker would land on the wrong character.
 *   2. Arrow-key movement skipped over replaced ranges unpredictably.
 *
 * Mark decorations keep the characters IN the DOM (so CM6's character-
 * level position map stays complete) but make them visually invisible
 * via CSS. The key CSS trick is `font-size: 0` which collapses the
 * text node to zero width/height while CM6 still knows those positions
 * exist. This is the same approach  uses for marker hiding.
 */
const hideMarker = Decoration.mark({ class: "mz-lp-hidden" });

/**
 * Heading decorations applied at the LINE level (not as mark spans).
 *
 * Using `Decoration.line` to set the class on the line's wrapping div
 * lets CM6 correctly measure line heights via `lineBlockAt`. The old
 * `Decoration.mark` approach wrapped only the heading text in a span
 * with `font-size: 1.8em`, and CM6's cached line-block heights stayed
 * at the normal line height until a later measure cycle — so clicks
 * on a heading landed on the line BELOW it (the "click on H1, cursor
 * jumps down" bug the user kept reporting). Line decorations invalidate
 * CM6's height cache correctly.
 */
const headingLineDeco: Record<number, Decoration> = {
    1: Decoration.line({ class: "mz-lp-h1-line" }),
    2: Decoration.line({ class: "mz-lp-h2-line" }),
    3: Decoration.line({ class: "mz-lp-h3-line" }),
    4: Decoration.line({ class: "mz-lp-h4-line" }),
    5: Decoration.line({ class: "mz-lp-h5-line" }),
    6: Decoration.line({ class: "mz-lp-h6-line" }),
};

const boldDeco = Decoration.mark({ class: "mz-lp-bold" });
const italicDeco = Decoration.mark({ class: "mz-lp-italic" });
const strikethroughDeco = Decoration.mark({ class: "mz-lp-strikethrough" });
const underlineDeco = Decoration.mark({ class: "mz-lp-underline" });
const highlightDeco = Decoration.mark({ class: "mz-lp-highlight" });
const inlineCodeDeco = Decoration.mark({ class: "mz-lp-inline-code" });
const orderedMarkerDeco = Decoration.mark({ class: "mz-lp-ordered-marker" });
const listContentDeco = Decoration.mark({ class: "mz-lp-list-content" });
const linkDeco = Decoration.mark({ class: "mz-lp-link" });
// linkUrlDeco removed — link URLs are hidden in preview
// Blockquote + HR: same reasoning as headings — use line decorations so
// their padding / border changes invalidate CM6's height cache and
// clicks map to the correct source line.
const blockquoteLineDeco = Decoration.line({ class: "mz-lp-blockquote-line" });
const hrLineDeco = Decoration.line({ class: "mz-lp-hr-line" });
function listGuideDeco(level: number): Decoration {
    return Decoration.line({
        class: "mz-lp-list-guides",
        attributes: {
            style: `--mz-list-level: ${level};`,
        },
    });
}

function listWrapDeco(
    level: number,
    markerChars: number,
    residualSpaces: number,
): Decoration {
    return Decoration.line({
        class: "mz-list-wrap-line",
        attributes: {
            style: `--mz-list-wrap-tabs: ${level}; --mz-list-wrap-spaces: ${residualSpaces}; --mz-list-wrap-marker: ${markerChars};`,
        },
    });
}

function measureListIndentWidth(view: EditorView): number {
    if (typeof document === "undefined") {
        return LIST_INDENT_WIDTH * 8 + LIST_INDENT_EXTRA_PX;
    }

    const probe = document.createElement("span");
    probe.textContent = "\t";
    probe.style.position = "absolute";
    probe.style.visibility = "hidden";
    probe.style.pointerEvents = "none";
    probe.style.whiteSpace = "pre";
    probe.style.padding = "0";
    probe.style.margin = "0";
    probe.style.border = "0";
    probe.style.font = getComputedStyle(view.contentDOM).font;
    probe.style.tabSize = `${LIST_RENDER_TAB_SIZE}`;
    probe.style.setProperty("-moz-tab-size", `${LIST_RENDER_TAB_SIZE}`);
    view.contentDOM.appendChild(probe);
    const measured = probe.getBoundingClientRect().width;
    probe.remove();
    if (Number.isFinite(measured) && measured > 0) {
        return measured + LIST_INDENT_EXTRA_PX;
    }

    return (
        Math.max(1, view.defaultCharacterWidth) * LIST_INDENT_WIDTH +
        LIST_INDENT_EXTRA_PX
    );
}

function syncListGuideMetrics(view: EditorView) {
    const rawIndentWidth = Math.max(
        40,
        Math.round(measureListIndentWidth(view)),
    );
    const indentWidth =
        rawIndentWidth % 2 === 0 ? rawIndentWidth : rawIndentWidth + 1;
    const guideOffset = Math.max(1, indentWidth / 2);
    view.contentDOM.style.setProperty("tab-size", `${indentWidth}px`);
    view.contentDOM.style.setProperty("-moz-tab-size", `${indentWidth}px`);
    view.contentDOM.style.setProperty(
        "--mz-list-indent-step",
        `${indentWidth}px`,
    );
    view.contentDOM.style.setProperty(
        "--mz-list-guide-offset",
        `${guideOffset}px`,
    );
}

function eventTargetElement(target: EventTarget | null): Element | null {
    if (target instanceof Element) return target;
    return target instanceof Node ? target.parentElement : null;
}

function isUnorderedListLine(text: string): boolean {
    return /^\s*[-*+]\s+/.test(text);
}

function isFenceLine(text: string): boolean {
    return /^(`{3,}|~{3,})/.test(text);
}

function isHorizontalRuleLine(text: string): boolean {
    return /^\s{0,3}(-{3,}|\*{3,}|_{3,})\s*$/.test(text);
}

function horizontalRuleCursorPos(line: { from: number; text: string }): number {
    const match = line.text.match(/^(\s{0,3})(-{3,}|\*{3,}|_{3,})/);
    if (!match) return line.from + line.text.length;
    return line.from + match[1].length + match[2].length;
}

function lineFromDomTarget(
    view: EditorView,
    target: EventTarget | null,
): {
    element: HTMLElement;
    line: ReturnType<typeof view.state.doc.line>;
} | null {
    const lineElement = eventTargetElement(target)?.closest(".cm-line");
    if (
        !(lineElement instanceof HTMLElement) ||
        !view.dom.contains(lineElement)
    ) {
        return null;
    }

    try {
        return {
            element: lineElement,
            line: view.state.doc.lineAt(view.posAtDOM(lineElement, 0)),
        };
    } catch {
        return null;
    }
}

function visibleTextRight(element: HTMLElement): number | null {
    const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
    let maxRight: number | null = null;
    let node: Node | null;

    while ((node = walker.nextNode())) {
        const range = document.createRange();
        range.selectNodeContents(node);
        for (const rect of Array.from(range.getClientRects())) {
            if (rect.width > 0.5) {
                maxRight =
                    maxRight === null
                        ? rect.right
                        : Math.max(maxRight, rect.right);
            }
        }
        range.detach();
    }

    return maxRight;
}

function domCaretPositionFromPoint(
    view: EditorView,
    event: MouseEvent,
): number | null {
    try {
        const caretPosition = document.caretPositionFromPoint?.(
            event.clientX,
            event.clientY,
        );
        if (caretPosition) {
            return view.posAtDOM(
                caretPosition.offsetNode,
                caretPosition.offset,
            );
        }

        const legacyDocument = document as Document & {
            caretRangeFromPoint?: (
                x: number,
                y: number,
            ) => globalThis.Range | null;
        };
        const caretRange = legacyDocument.caretRangeFromPoint?.(
            event.clientX,
            event.clientY,
        );
        if (caretRange) {
            return view.posAtDOM(
                caretRange.startContainer,
                caretRange.startOffset,
            );
        }
    } catch {
        return null;
    }

    return null;
}

function clampToLine(pos: number, line: { from: number; to: number }): number {
    return Math.min(line.to, Math.max(line.from, pos));
}

const listLineBoundaryClickHandler = EditorView.domEventHandlers({
    mousedown(event: MouseEvent, view: EditorView) {
        if (
            event.button !== 0 ||
            event.ctrlKey ||
            event.metaKey ||
            event.altKey
        ) {
            return false;
        }

        const domLine = lineFromDomTarget(view, event.target);
        if (!domLine || !isUnorderedListLine(domLine.line.text)) return false;

        const nextLine =
            domLine.line.number < view.state.doc.lines
                ? view.state.doc.line(domLine.line.number + 1)
                : null;
        const needsBoundaryCorrection =
            domLine.line.text.includes("[[") ||
            (nextLine !== null && isFenceLine(nextLine.text));
        if (!needsBoundaryCorrection) return false;

        const pos = view.posAtCoords({ x: event.clientX, y: event.clientY });
        if (pos === null) return false;

        const mappedLine = view.state.doc.lineAt(pos);
        if (mappedLine.number === domLine.line.number) return false;

        const caretPos = domCaretPositionFromPoint(view, event);
        const textRight = visibleTextRight(domLine.element);
        const targetPos =
            caretPos !== null &&
            caretPos >= domLine.line.from &&
            caretPos <= domLine.line.to
                ? caretPos
                : textRight !== null && event.clientX >= textRight - 1
                  ? domLine.line.to
                  : clampToLine(pos, domLine.line);

        event.preventDefault();
        view.dispatch({
            selection: EditorSelection.cursor(targetPos),
            scrollIntoView: true,
        });
        view.focus();
        return true;
    },
});

const horizontalRuleClickHandler = EditorView.domEventHandlers({
    mousedown(event: MouseEvent, view: EditorView) {
        if (
            event.button !== 0 ||
            event.ctrlKey ||
            event.metaKey ||
            event.altKey
        ) {
            return false;
        }

        const domLine = lineFromDomTarget(view, event.target);
        if (!domLine || !isHorizontalRuleLine(domLine.line.text)) return false;

        event.preventDefault();
        view.dispatch({
            selection: EditorSelection.cursor(
                horizontalRuleCursorPos(domLine.line),
            ),
            scrollIntoView: true,
        });
        view.focus();
        return true;
    },
});
